'use strict';
const propBeforeAnimatedText=prop;
function textPartsAt(o,t){const text=String(o.text||''),f=clamp((t-clipStart(o))/(o.textDuration||1),0,1);if(o.textEffect==='typewriter')return{text:text.slice(0,Math.floor(f*text.length)),f};if(o.textEffect==='word-pop'){const words=text.split(/\s+/);return{text:words.slice(0,Math.ceil(f*words.length)).join(' '),f}}return{text,f}}
prop=function(c,o,v){if(o.type!=='text')return propBeforeAnimatedText(c,o,v);const {text,f}=textPartsAt(o,time),size=o.fontSize||42;c.save();c.translate(v.x,v.y);c.rotate(v.rotation*Math.PI/180);c.scale(v.scale,v.scale);c.globalAlpha=v.opacity*(o.textEffect==='fade'?f:1);if(o.textEffect==='rise'){c.translate(0,(1-f)*35);c.globalAlpha*=f}if(o.textEffect==='word-pop'){const n=String(o.text).split(/\s+/).length,p=f*n-Math.floor(f*n),scale=1+Math.sin(p*Math.PI)*.045;c.scale(scale,scale)}c.font=`${o.textWeight||600} ${size}px ${o.textFont==='sans'?'Arial, sans-serif':'Georgia, serif'}`;c.fillStyle=o.color||'#31564d';c.textAlign='center';text.split('\n').forEach((line,i)=>c.fillText(line,0,i*size*1.2));c.restore()};
const textControlsBefore=renderControls;renderControls=function(){textControlsBefore();const o=object();if(o?.type!=='text')return;const panel=document.createElement('details');panel.open=true;panel.innerHTML='<summary>Animated text</summary><label>Animation<select id="textAnimation"><option value="none">None</option><option value="typewriter">Typewriter</option><option value="word-pop">Word by word</option><option value="rise">Rise & fade</option><option value="fade">Fade in</option></select></label><label>Time (s)<input id="textAnimationTime" type="number" min="0.1" max="30" step="0.1"></label><label>Font<select id="textFont"><option value="serif">Editorial serif</option><option value="sans">Clean sans</option></select></label><div class="posegrid"><button data-title="headline">Headline</button><button data-title="lower">Lower third</button><button data-title="subtitle">Subtitle</button></div>';$('controls').prepend(panel);$('textAnimation').value=o.textEffect||'none';$('textAnimationTime').value=o.textDuration||1;$('textFont').value=o.textFont||'serif';$('textAnimation').onchange=e=>{o.textEffect=e.target.value;save();draw()};$('textAnimationTime').onchange=e=>{o.textDuration=clamp(+e.target.value||1,.1,30);save();draw()};$('textFont').onchange=e=>{o.textFont=e.target.value;save();draw()};panel.querySelectorAll('[data-title]').forEach(b=>b.onclick=()=>{const kind=b.dataset.title;o.fontSize=kind==='headline'?58:kind==='lower'?30:24;o.textFont='sans';o.textEffect=kind==='headline'?'word-pop':kind==='lower'?'rise':'typewriter';setKey(o,{...stateAt(o,time),x:480,y:kind==='headline'?240:kind==='lower'?430:480});render()});panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o.locked)};
const plainCaptions=drawCaptions;
drawCaptions=function(c,s,t){if(!s.captionStyle||s.captionStyle.mode==='plain')return plainCaptions(c,s,t);const captions=(s.captions||[]).filter(x=>t>=x.start&&t<x.end);if(!captions.length)return;const style=s.captionStyle,size=style.size||27;c.save();c.font='600 '+size+'px Arial';c.textBaseline='middle';const tokens=[];for(const caption of captions){const words=caption.text.trim().split(/\s+/);for(let i=0;i<words.length;i++){const word=caption.words?.[i],start=word?.start??caption.start+i/words.length*(caption.end-caption.start),end=word?.end??caption.start+(i+1)/words.length*(caption.end-caption.start);tokens.push({text:words[i],active:t>=start&&t<end,width:c.measureText(words[i]+' ').width})}}const rows=[[]];let width=0;for(const token of tokens){if(width+token.width>820&&rows.at(-1).length){rows.push([]);width=0}rows.at(-1).push(token);width+=token.width}const shown=rows.slice(0,3),height=shown.length*(size+11)+16,top=style.position==='top'?35:style.position==='center'?270-height/2:520-height;rect(c,45,top,870,height,'rgba(12,15,20,.88)',8);shown.forEach((row,i)=>{let x=480-row.reduce((n,w)=>n+w.width,0)/2;const y=top+12+(i+.5)*(size+11);for(const token of row){if(token.active)rect(c,x-3,y-size/2-4,token.width+1,size+8,style.highlight||'#e5b75d',4);c.fillStyle=token.active?'#15171c':'#fffaf0';c.textAlign='left';c.fillText(token.text,x,y);x+=token.width}});c.restore()};
const textValidator=valid;valid=function(p){return textValidator(p)&&p.scenes.every(s=>(!s.captionStyle||['plain','highlight'].includes(s.captionStyle.mode)&&Number.isFinite(s.captionStyle.size)&&s.captionStyle.size>=16&&s.captionStyle.size<=60&&['bottom','top','center'].includes(s.captionStyle.position))&&s.objects.every(o=>(!o.textEffect||['none','typewriter','word-pop','rise','fade'].includes(o.textEffect))&&(o.textDuration===undefined||Number.isFinite(o.textDuration)&&o.textDuration>=.1&&o.textDuration<=30)))};
render();
